INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '罚时', '凯迪拉克车手有明显的dive in行为，扎入弯中没有考虑到外线车辆出弯角度，因而判罚扣除安全分3分罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T17:03:05.228Z');
