INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '罚时', '凯迪拉克车手有明显鱼雷行为，导致Alpine车手失控冲出赛道，丢失位置，因而按照判罚规则扣除3分安全分罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T17:00:55.941Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '安全分变动', '凯迪拉克车手有明显鱼雷行为，导致Alpine车手失控冲出赛道，丢失位置，因而按照判罚规则扣除3分安全分罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T17:00:50.162Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '罚时', '凯迪拉克车手在进入弯内占据内线，和It57达成并排条件，但出弯没有给外线车辆留出合理过弯空间，将Alpine车手推出赛道丢失位置，因而按照白皮书6.1条例扣除安全分3分罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:57:41.969Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '安全分变动', '凯迪拉克车手在进入弯内占据内线，和It57达成并排条件，但出弯没有给外线车辆留出合理过弯空间，将Alpine车手推出赛道丢失位置，因而按照白皮书6.1条例扣除安全分3分罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:57:36.173Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'AyatoSeven', 'AyatoSeven', '罚时', '奥迪车手在弯中前轮超过马丁后轮，达成部分并排，马丁并未留出过弯空间，因而按照白皮书6.1条例扣除安全分3分，罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:54:54.970Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'AyatoSeven', 'AyatoSeven', '安全分变动', '奥迪车手在弯中前轮超过马丁后轮，达成部分并排，马丁并未留出过弯空间，因而按照白皮书6.1条例扣除安全分3分，罚时5秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:54:48.674Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, '叶yeeeeee', '叶yeeeeee', '安全分变动', '根据赛前简报和白皮书5.2.4条例明确指出，排位赛不得无故驶出赛道（包括排位赛出站、回场圈切弯抄近路），因而判处扣除安全分3分罚时5秒，因车手DNF转换为扣除安全分5分', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:51:00.136Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '罚时', '根据赛后成绩单时间戳和视频中车辆视角，UbisoftHongKong确实存在赛道外切弯超车，根据白皮书6.1判罚规则扣除安全分2分，罚时3秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:43:54.792Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 4, 'UbisoftHongKong', 'UbisoftHongKong', '安全分变动', '根据赛后成绩单时间戳和视频中车辆视角，UbisoftHongKong确实存在赛道外切弯超车，根据白皮书6.1判罚规则扣除安全分2分，罚时3秒', NULL, 'Er1sed-FOX', NULL, '2026-09-10T16:43:46.170Z');
