INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, 'Er1sed-FOX', 'Er1sed-FOX', '安全分变动', '其一，根据规则5.4.1D、5.4.1I，T1外线车辆Er1sed-FOX满足规则5.4.1D完全并排，对于T1外线Er1sed-FOX的判定：满足完全并排条件且相较于内线车，有增加车身重叠的趋势且后方车辆有足够的入弯角度；对于T1内线芒果的路权判定：满足前轮超越前车后轮且有足够的入弯角度。综上，两车拥有相等路权。
其二，根据规则5.4.1J、5.4.3，Er1sed-FOX在缠斗中虽拥有相等路权，但因T1弯心处需为芒果留出内线空间导致其出现大量转向不足，并在出弯时四轮出线（此处黄线为赛道边界），不属于车手被动受迫避让，因此满足“失位(5.4.1J)”。赛事干事(Mirrorcc)认为，安全车刚恢复后的T1采用外线超车难度极大，因此作为率先失位（离开赛道）的车手，Er1sed-FOX需要避免再次返回赛道时可能引发的碰撞。Er1sed-FOX需承担事故主要责任。', NULL, 'Mirrorcc', 240, '2026-07-24T18:06:46.933Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, '芒果', '芒果', '罚时', '双车并排进入组合弯，拥有同等路权，视频车给予充分的一车空间但芒果并没有在出弯时给予视频车任何空间导致后车损失大量时间故承担碰撞全部责任', NULL, 'It57', 240, '2026-07-24T16:17:41.091Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, '芒果', '芒果', '安全分变动', '双车并排进入组合弯，拥有同等路权，视频车给予充分的一车空间但芒果并没有在出弯时给予视频车任何空间导致后车损失大量时间故承担碰撞全部责任', NULL, 'It57', 240, '2026-07-24T16:17:48.824Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, '芒果', '芒果', '安全分变动', '根据规则5.4.7，芒果在Perez入弯点（5.4.1H）前满足进攻条件且两车拥有相等路权（满足5.4.1I判定条件），但由于T3-T4为连续弯道，路权的判定需以T3（连续弯的第一个弯道）为主。T3弯心处Perez与Landoooo_W缠斗时芒果作为Perez后车，追尾Perez并导致Perez出弯严重转向不足，偏离正常赛车线，导致T4处入弯线路受阻，引发碰撞并导致Perez与后车损失大量时间。因此芒果负事故主要责任。', NULL, 'Mirrorcc', 230, '2026-07-24T18:19:31.969Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, '芒果', '芒果', '罚时', '根据规则5.4.7，芒果在Perez入弯点（5.4.1H）前满足进攻条件且两车拥有相等路权（满足5.4.1I判定条件），但由于T3-T4为连续弯道，路权的判定需以T3（连续弯的第一个弯道）为主。T3弯心处Perez与Landoooo_W缠斗时芒果作为Perez后车，追尾Perez并导致Perez出弯严重转向不足，偏离正常赛车线，导致T4处入弯线路受阻，引发碰撞并导致Perez车辆受损、后方多辆赛车损失大量时间。因此芒果负事故主要责任。', NULL, 'Mirrorcc', 230, '2026-07-24T18:21:00.404Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, '叶yeeeeee', '叶yeeeeee', '安全分变动', '根据规则5.4.1i，双方均有相等路权，当且仅当前车在通过弯道（）的任一时刻后轮完全超过后车的前轮，且后续行驶两车的车身重叠有减少的趋势时，前车才拥有全部路权。
因此根据规则5.4.2，比赛中任何时候都需为对手留出合理空间（5.4.1F），不得侵占拥有相等路权及以上路权的对手的行驶线路。因此叶yeeeeee应承担事故的主要责任。', NULL, 'Mirrorcc', 229, '2026-07-24T18:48:37.599Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 1, 'Perez', 'Perez', '安全分变动', '超出赛道限制>3次/切弯', NULL, 'Er1sed-FOX', NULL, '2026-07-24T16:02:46.184Z');
