INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'dan', 'dan', '安全分变动', 'dan的进攻不满足规则5.4.7条款，由于此处并非常规超车点，这样过于乐观的超车动作存在引发事故的风险，因前车未违反防守规则并已导致前车损失，后车主责。', NULL, 'Mirrorcc', 251, '2026-07-29T16:17:29.232Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'dan', 'dan', '罚时', 'dan的进攻不满足规则5.4.7条款，由于此处并非常规超车点，这样过于乐观的超车动作存在引发事故的风险，因前车未违反防守规则并已导致前车损失，后车主责。', NULL, 'Mirrorcc', 251, '2026-07-29T16:17:41.259Z');
