INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'dan', 'dan', '安全分变动', '经dan的主视角判断，dan未驶离赛道（离开赛道边界），不属于危险返回赛道。但直道上的转向是在两车有车身重叠且在增加时做出的，影响到后车线路。', NULL, 'Mirrorcc', 254, '2026-07-29T16:28:44.644Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'Er1sed-FOX', 'Er1sed-FOX', '安全分变动', 'Er1sed-FOX在躲避事故时未充分观察到左侧ColorFirst，避让时引发两车碰撞，导致ColorFirst产生车损并丢失赛道位置。', NULL, 'Mirrorcc', 255, '2026-07-29T16:33:25.699Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'Er1sed-FOX', 'Er1sed-FOX', '罚时', 'Er1sed-FOX在躲避事故时未充分观察到左侧ColorFirst，避让时引发两车碰撞，导致ColorFirst产生车损并丢失赛道位置。', NULL, 'Mirrorcc', 255, '2026-07-29T16:33:30.529Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'ColorFirst', 'ColorFirst', '安全分变动', '凯迪拉克老吴k423左侧小红牛赛车应该是colorfirst', NULL, 'Mirrorcc', 256, '2026-07-29T23:49:01.679Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'WuHen', 'WuHen', '安全分变动', '经赛会查看老吴k423主观视角，wuhen存在引发碰撞的违规变线，wuhen违反规则5.4.4，负主要责任。', NULL, 'Mirrorcc', 256, '2026-07-29T16:36:51.782Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 2, 'WuHen', 'WuHen', '安全分变动', 'colorfirst在发车起步时向右变线引发碰撞，导致老吴k423与fox速度受影响；同时后车wuhen选择内线进T1，虽达成部分并排但进弯角度非常小，属于不合理进弯线路，应放弃进攻', NULL, 'Mirrorcc', 256, '2026-07-30T00:23:51.198Z');
