INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 3, 'It57', 'It57', '安全分变动', '法拉利车手it57及其强硬地切过维修区入口左侧草坪进站，并未遵守赛前简报要点第二条“正赛维修区入站的赛车须在慢速弯出弯时保持右侧行驶，禁止从左侧横切至右侧线路进站”，且奥迪车手lm10已相应减速，避免维修区入口处事故和可能触发的安全车，因而从重处罚', NULL, 'Er1sed-FOX', 258, '2026-07-31T17:55:31.029Z');
