INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 7, 'dan', 'dan', '安全分变动', 'dan在T5处失误上墙，撞车退赛的同时导致候车LewisRen前翼严重受损，因此对dan作出处罚。', NULL, 'Mirrorcc', 278, '2026-08-10T14:40:57.933Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 7, 'dan', 'dan', '安全分变动', 'dan在T5处失误上墙，撞车退赛的同时导致候车LewisRen前翼严重受损，因此对dan作出处罚。（dan已退赛，按联赛规则罚时5s减半记入安全分-2.5）', NULL, 'Mirrorcc', 278, '2026-08-10T14:41:03.309Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, '叶yeeeeee', '叶yeeeeee', '安全分变动', '奥迪和凯迪拉克首先满足13号弯并排条件，因此处非常规超车点，凯迪拉克在13号弯并排时右侧尚留有空间，因距离过近导致第一次碰撞，此时奥迪已进入正常14号弯线路，凯迪拉克因上一弯撞墙后失控并未减速从而导致事故发生。根据6.1判罚规则，导致他人退赛+出动安全车应扣除10分安全分，但同一事件不叠加，且凯迪拉克DNF，因此原先5分10秒处罚改为扣除安全分10（5+10/2=5）执行', NULL, 'Er1sed-FOX', 284, '2026-08-12T15:04:57.309Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, 'Landoooo_W', 'Landoooo_W', '警告', '13号弯弯心并排时有未造成车损的轻微接触，因赛后DNF故扣除1分安全分改为警告', NULL, 'Er1sed-FOX', 284, '2026-08-12T15:09:22.107Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, 'Gougou', 'Gougou', '荣誉分变动', 'Gougou并未在飞驰圈，理应给飞行圈车辆让车，由于赛前简报对摩纳哥的规则特例，此时场内有15辆赛车，排位赛阻挡扣除3分改为扣除1分执行', NULL, 'Er1sed-FOX', 282, '2026-08-12T15:26:40.726Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, 'ColorFirst', 'ColorFirst', '安全分变动', '违反蓝旗规定，蓝旗下未及时让车，造成哈斯速度丢失', NULL, 'Er1sed-FOX', 287, '2026-08-12T15:45:53.074Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, 'Er1sed-FOX', 'Er1sed-FOX', '安全分变动', 'fox在黄旗下超车被ea判定为非法超车须交还位置，但让车时fox在行车线上且有明显刹车动作，故负事故主要责任', NULL, 'Mirrorcc', 283, '2026-08-12T16:14:17.608Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 8, 'Er1sed-FOX', 'Er1sed-FOX', '罚时', 'fox在黄旗下超车被ea判定为非法超车须交还位置，但让车时fox在行车线上且有明显刹车动作，故负事故主要责任', NULL, 'Mirrorcc', 283, '2026-08-12T16:14:29.466Z');
