INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 10, '高木同学重度依赖', '高木同学重度依赖', '安全分变动', '根据规则5.2.1在排位赛中，车手需在赛道上与前后车辆保持合适间距后，再开始飞行圈，前车并未保证合适间距阻挡了他人的飞行圈', NULL, 'It57', 291, '2026-08-16T15:53:21.289Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 10, 'tenbergen', 'tenbergen', '罚时', '在出弯阶段后车追尾前车，导致前车失控丢失大量时间', NULL, 'It57', 293, '2026-08-16T15:57:12.326Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 10, 'tenbergen', 'tenbergen', '安全分变动', '在出弯阶段后车追尾前车，导致前车失控丢失大量时间', NULL, 'It57', 293, '2026-08-16T15:57:43.227Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 10, 'LewisRen', 'LewisRen', '警告', 'tenbergen超车时未考虑后车相对位置，走交叉线的时机并不成熟，影响到LewisRen的进弯节奏并引发碰撞，鉴于两车均未有明显失控或失误，外线车辆在驶过弯心后未留出足够的内线空间，两车均未有避让动作，因此为赛道事故。', NULL, 'Mirrorcc', 294, '2026-08-17T00:26:54.556Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 10, 'tenbergen', 'tenbergen', '警告', 'tenbergen超车时未考虑后车相对位置，走交叉线的时机并不成熟，影响到LewisRen的进弯节奏并引发碰撞，鉴于两车均未有明显失控或失误，外线车辆在驶过弯心后未留出足够的内线空间，两车均未有避让动作，因此为赛道事故。', NULL, 'Mirrorcc', 294, '2026-08-17T00:27:01.820Z');
