INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 13, 'AyatoSeven', 'AyatoSeven', '罚时', 'AyatoSeven及其强硬地大幅度变线完全切过维修区入口进站，且与Er1sed-FOX发生碰撞，并产生车损，维修区入口处事故和可能触发的安全车，因而从重处罚碰撞，并产生车损，维修区入口处事故和可能触发的安全车，因而从重处罚', NULL, 'It57', 308, '2026-08-24T15:23:06.426Z');
