INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 14, 'star-falI04', 'star-falI04', '罚时', '前车在弯心处的二次刹车动作有阻挡后车的嫌疑，后车追尾后在有车身接触时仍踩油门，从后车刹车点开始两车就有相对位置的减小，因此后车有保持安全车距的义务，后车负主要责任。关于一审中前车或后车恶意驾驶的问题，就驾驶行为来看前后车的操作均属于正常行为，且赛会无法从事故录像中判断车手主观驾驶行为，因此双方就此警告一次。', NULL, 'Mirrorcc', 316, '2026-08-28T04:57:58.093Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 14, 'star-falI04', 'star-falI04', '警告', '前车在弯心处的二次刹车动作有阻挡后车的嫌疑，后车追尾后在有车身接触时仍踩油门，从后车刹车点开始两车就有相对位置的减小，因此后车有保持安全车距的义务，后车负主要责任。关于一审中前车或后车恶意驾驶的问题，就驾驶行为来看前后车的操作均属于正常行为，且赛会无法从事故录像中判断车手主观驾驶行为，因此双方就此警告一次。', NULL, 'Mirrorcc', 316, '2026-08-28T04:58:18.651Z');
