INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 15, 'Landoooo_W', 'Landoooo_W', '安全分变动', '因视频清晰度较低，故作出以下判罚：后车在过线进行飞行圈时已出示黄旗，车手并未减速或关闭boost模式，此时前车因失控撞毁米牌并横于赛道上，后车无法躲闪导致前车退赛、前翼损坏。因此根据白皮书5.2.5条例引据5.4判罚车手Landoooo_W扣除安全分3分罚时五秒，同时对Swizzet3271的未减速行为进行警告。', NULL, 'Er1sed-FOX', 321, '2026-08-28T16:03:55.217Z');
