INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 18, 'Momokong', 'Momokong', '罚时', '投诉方描述中关于规则5.3.4、5.3.8、5.3.11所述符合视频所述，tenbergen与momokong投诉并案处理，对ayatoseven判决如下', NULL, 'Mirrorcc', 333, '2026-09-10T04:14:01.981Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 18, 'Er1sed-FOX', 'Er1sed-FOX', '安全分变动', '根据5.4.12：赛车在常规刹车点之前松油滑行充电（不包括刹车），lico时后车追尾，后车负事故全部责任，除非前车过早松油（若涉及前后 车刹车区内一次或多次变线的，则由赛会判定）。在该事故中，FOX在lico过程中在约150m的位置向左变线，导致后车追尾并造成后车前翼车损。', NULL, 'Mirrorcc', 332, '2026-09-10T12:10:14.290Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 18, 'Er1sed-FOX', 'Er1sed-FOX', '罚时', '根据5.4.12：赛车在常规刹车点之前松油滑行充电（不包括刹车），lico时后车追尾，后车负事故全部责任，除非前车过早松油（若涉及前后 车刹车区内一次或多次变线的，则由赛会判定）。在该事故中，FOX在lico过程中在约150m的位置向左变线，导致后车追尾并造成后车前翼车损。', NULL, 'Mirrorcc', 332, '2026-09-10T12:10:36.951Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 19, 'Beast', 'Beast', '安全分变动', '确认车手Beast在弯中与Ak_Langley_S并排时没有留出空间，因此Ak_Langley_S的此处超出赛道边界消除，由于Ak_Langley_S共计4次超出赛道边界，因而罚时不予消除，并处Beast扣除安全分3分罚时5秒', NULL, 'Er1sed-FOX', 335, '2026-09-11T14:38:04.923Z');
