INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 19, 'Momokong', 'Momokong', '安全分变动', 'Momokong进攻前未建立任何路权，违反5.4.7(未拥有相等路权应放弃进攻)与5.4.6(后车应主动避免追尾)，属于5.4.5危险进攻。', NULL, 'Mirrorcc', 338, '2026-09-12T06:53:09.477Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 19, 'Momokong', 'Momokong', '罚时', 'Momokong进攻前未建立任何路权，违反5.4.7(未拥有相等路权应放弃进攻)与5.4.6(后车应主动避免追尾)，属于5.4.5危险进攻。', NULL, 'Mirrorcc', 338, '2026-09-12T06:53:16.565Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 19, 'FerrariGoat', 'FerrariGoat', '警告', '该超车属于赛道合理攻防，驶离弯心时两车稍有擦碰，如果说ferrarigoat出弯一定要给fox留出一车宽的空间，那在ferrarigoat到达出弯位置前，在弯心处fox也应留足一车宽空间。此处高速弯连续弯超车难度极大，客观上并排的两车无法给对方留出足够的空间，ferrarigoat迫使其他赛车驶离赛道程度较轻。', NULL, 'Mirrorcc', 337, '2026-09-12T07:03:21.939Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '4', 19, 'Ak_Langley_S', 'Ak_Langley_S', '安全分变动', 'ak出三号弯后与gougou有部分车身重叠且前者未留出足够赛道空间，导致两车在T4前的直路发生碰撞，ak在发生碰撞后驶入内线，后车躲闪不及引发较为严重的事故。', NULL, 'Mirrorcc', 336, '2026-09-12T07:08:04.964Z');
