INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'A380FatLiner', 'A380FatLiner', '安全分变动', '确认a380并未在蓝旗下让车', NULL, 'It57', 377, '2026-10-16T14:46:36.049Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'Sliced Onion', 'Sliced-Onion', '安全分变动', '根据规则5.4.1i关于路权的判定，T1入弯前后车均满足非内线车辆的三点要求（后车在通过弯道的任一时刻前轮中心点到达前方车辆的后轮中心点、增加车身重叠的趋势、拥有足够的入弯角度），因此T1不存在未达成并排条件。同时，根据连续弯以第一个弯道的情况为准进行事故判定的原则（规则5.4.1i同上），T1、T2两处均需要双方留出两侧足够的空间。FOX在这里并未离开赛道，因赛道边界为白色实线而非黄色，所以不存在挤压对手驶离赛道，但FOX在T2的绝大部分弯心位置已被挤占，仅轮胎压在白线上，因此Sliced Onion仍需负过度挤压对手的责任，更正判罚如下。', NULL, 'Mirrorcc', 376, '2026-10-17T14:58:59.799Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'Sliced Onion', 'Sliced-Onion', '罚时', '两车于一号弯形成并排进入二号弯，内线车理应获得空间，外线车并未留出丝毫空间', NULL, 'It57', 376, '2026-10-16T14:58:03.894Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'Sliced Onion', 'Sliced-Onion', '安全分变动', '两车于一号弯形成并排进入二号弯，内线车理应获得空间，外线车并未留出丝毫空间', NULL, 'It57', 376, '2026-10-16T14:58:14.817Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'Sliced Onion', 'Sliced-Onion', '警告', '两车于一号弯形成并排进入二号弯，内线车理应获得空间，外线车并未留出丝毫空间', NULL, 'It57', 376, '2026-10-16T14:58:20.886Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'It57', 'It57', '安全分变动', '根据规则5.4.1i有关非内线赛车路权的判定以及连续弯以第一个弯道为准的判罚原则，It57在T1-T2两个弯道均与A380拥有相同路权，但由于It57在T1的“极致”线路，导致其在T2的线路偏离了正常赛车线，内线与之有车身重叠的仅A380一辆赛车，在T1弯心后It57与A380便有车身重叠，发生碰撞时It57作为超车一方，未及时注意到内线赛车的相对位置，A380作为防守方误判了T2左侧空间，未能及时修正车头方向，双方均存在非受迫性原因导致引发碰撞，导致A380与Momokong产生车损并损失部分时间，因此均予以处罚。考虑到A380键盘设备的低操控性，予以从轻处罚。', NULL, 'Mirrorcc', 379, '2026-10-17T15:35:20.468Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'A380FatLiner', 'A380FatLiner', '警告', '根据规则5.4.1i有关非内线赛车路权的判定以及连续弯以第一个弯道为准的判罚原则，It57在T1-T2两个弯道均与A380拥有相同路权，但由于It57在T1的“极致”线路，导致其在T2的线路偏离了正常赛车线，内线与之有车身重叠的仅A380一辆赛车，在T1弯心后It57与A380便有车身重叠，发生碰撞时It57作为超车一方，未及时注意到内线赛车的相对位置，A380作为防守方误判了T2左侧空间，未能及时修正车头方向，双方均存在非受迫性原因导致引发碰撞，导致A380与Momokong产生车损并损失部分时间，因此均予以处罚。考虑到A380键盘设备的低操控性，予以从轻处罚。', NULL, 'Mirrorcc', 379, '2026-10-17T15:35:27.842Z');
INSERT OR REPLACE INTO penalties (source, league, season, round, driver, driver_id, type, reason, points, handled_by, protest_id, created_at) VALUES ('mxbei', 'mengxin', '5', 1, 'It57', 'It57', '罚时', 'It57与A380部分并排，转向时未留足空间引发碰撞导致后车车损', NULL, 'Ak_Langley_S', 379, '2026-10-16T17:27:48.772Z');
